input.command:
cd /work/workspace/documents && for f in halvorsen_loi.pdf hosting_agreement_excerpt.pdf saltline_side_letter.pdf; do echo "== $f =="; (pdftotext -layout "$f" - 2>/dev/null || python3 - "$f" <<'EOF'
import sys
try:
    from pypdf import PdfReader
except ImportError:
    from PyPDF2 import PdfReader
r = PdfReader(sys.argv[1])
for p in r.pages:
    print(p.extract_text())
EOF
) ; done

